{"policy":"permit (
    principal is User,
    action == Action::"approveBudget",
    resource is Campaign
)
when {
    (principal.roles.contains(Role::"AccountManager") ||
     principal.roles.contains(Role::"CampaignDirector")) &&
    principal == resource.preparedBy &&
    resource.budget + resource.contingency <= context.budgetContingencyThreshold &&
    context.mfaUsed
};

permit (
    principal is User,
    action == Action::"approveBudget",
    resource is Campaign
)
when {
    principal.roles.contains(Role::"CampaignDirector") &&
    principal != resource.preparedBy &&
    context.mfaUsed
};

forbid (
    principal is User,
    action == Action::"approveBudget",
    resource is Campaign
)
when {
    (principal.roles.contains(Role::"AccountManager") ||
     principal.roles.contains(Role::"CampaignDirector")) &&
    principal == resource.preparedBy &&
    resource.budget + resource.contingency > context.budgetContingencyThreshold
};

forbid (
    principal is User,
    action == Action::"approveBudget",
    resource is Campaign
)
when { !context.mfaUsed };

permit (
    principal is User,
    action == Action::"launchCampaign",
    resource is Campaign
)
when {
    principal == resource.advertiser &&
    resource.status == CampaignStatus::"BudgetApproved" &&
    resource.riskLabels.contains(context.requiredRiskLabel)
};

forbid (
    principal is User,
    action == Action::"launchCampaign",
    resource is Campaign
)
when { resource.status != CampaignStatus::"BudgetApproved" };

forbid (
    principal is User,
    action == Action::"launchCampaign",
    resource is Campaign
)
when { principal != resource.advertiser };

forbid (
    principal is User,
    action == Action::"launchCampaign",
    resource is Campaign
)
when { !resource.riskLabels.contains(context.requiredRiskLabel) };"}
